INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(39366, 0, 0, '%s disperses!', 16, 0, 100.0, 0, 0, 0, 0, 0, 'Sun-Touched Servant'),
(39369, 0, 0, '%s disperses!', 16, 0, 100.0, 0, 0, 0, 0, 0, 'Sun-Touched Sprite'),
(39378, 0, 0, 'Defilers! Wretches! Fiends! Begone from here!', 14, 0, 100.0, 0, 0, 18911, 0, 0, 'Rajh'),
(39378, 1, 0, 'Can you feel it? The blessed warmth of the sun?', 14, 0, 100.0, 0, 0, 18912, 0, 0, 'Rajh'),
(39378, 2, 0, 'I send you to your deity.', 14, 0, 100.0, 0, 0, 18914, 0, 0, 'Rajh to Player'),
(39378, 2, 1, 'I will take this life as an offering!', 14, 0, 100.0, 0, 0, 18913, 0, 0, 'Rajh to Player'),
(39378, 3, 0, 'Blazing rays of light, take me!', 14, 0, 100.0, 0, 0, 18910, 0, 0, 'Rajh to Player'),
(39425, 0, 0, 'Turn back, intruders! These halls must not be disturbed!', 14, 0, 100.0, 0, 0, 18580, 0, 0, 'Temple Guardian Anhuur - SAY_AGGRO'),
(39425, 1, 0, 'Beacons of light, bestow upon me your aegis!', 14, 0, 100.0, 0, 0, 18581, 0, 0, 'Temple Guardian Anhuur - SAY_SHIELD'),
(39425, 2, 0, '%s becomes protected by his defense beacons! Disable them by pulling the levers below!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Temple Guardian Anhuur - EMOTE_SHIELD'),
(39425, 3, 0, '%s is no longer protected by the beacons!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Temple Guardian Anhuur'),
(39425, 4, 0, 'I regret nothing.', 14, 0, 100.0, 0, 0, 18582, 0, 0, 'Temple Guardian Anhuur'),
(39425, 5, 0, 'What... have you... done?', 14, 0, 100.0, 0, 0, 18579, 0, 0, 'Temple Guardian Anhuur - SAY_DEATH'),
(39428, 0, 0, 'Ptah... is... no more...', 14, 0, 100.0, 0, 0, 18905, 0, 0, 'Earthrager Ptah - SAY_DEATH'),
(39428, 1, 0, 'More carrion for the swarm...', 14, 0, 100.0, 0, 0, 18906, 0, 0, 'Earthrager Ptah - SAY_AGGRO'),
(39428, 2, 0, 'Dust to dust.', 14, 0, 100.0, 0, 0, 18907, 0, 0, 'Earthrager Ptah - SAY_PLAYER_KILL'),
(39428, 3, 0, 'The earth TREMBLES!', 14, 0, 100.0, 0, 0, 18908, 0, 0, 'Earthrager Ptah - SAY_SPECIAL'),
(39731, 0, 0, 'This chamber will flourish with your life energy!', 14, 0, 100.0, 0, 0, 18571, 0, 0, 'Ammunae - Aggro'),
(39731, 1, 0, 'Your life, UNLEASHED!', 14, 0, 100.0, 0, 0, 18572, 0, 0, 'Ammunae - Rampant Growth'),
(39731, 2, 0, 'The cycle continues...', 14, 0, 100.0, 0, 0, 18569, 0, 0, 'Ammunae - Death'),
(39731, 3, 0, 'Wither away!', 14, 0, 100.0, 0, 0, 18573, 0, 0, 'Ammunae - Slay 1'),
(39731, 3, 1, 'Waste of energy.', 14, 0, 100.0, 0, 0, 18574, 0, 0, 'Ammunae - Slay 2'),
(39788, 0, 0, 'This unit has been activated outside normal operating protocols. Downloading new operational parameters. Download complete. Full unit self defense routines are now active. Destruction of foreign units in the system shall now commence.', 14, 0, 100.0, 0, 0, 20857, 0, 0, 'Anraphet - SAY_INTRO'),
(39788, 1, 0, 'Purge of unauthorized entities commencing.', 14, 0, 100.0, 0, 0, 20862, 0, 0, 'Anraphet - SAY_AGGRO'),
(39788, 2, 0, 'Omega Stance activated. Annihilation of foreign unit is now imminent.', 14, 0, 100.0, 0, 0, 20861, 0, 0, 'Anraphet - SAY_OMEGA_STANCE'),
(39788, 3, 0, 'Purge Complete.', 14, 0, 100.0, 0, 0, 20859, 0, 0, 'Anraphet - SAY_PLAYER_KILL'),
(39788, 3, 1, 'Target Annihilated.', 14, 0, 100.0, 0, 0, 20858, 0, 0, 'Anraphet - SAY_PLAYER_KILL'),
(39788, 4, 0, 'Anraphet unit shutting down...', 14, 0, 100.0, 0, 0, 20856, 0, 0, 'Anraphet - SAY_DEATH'),
(39908, 0, 0, 'This symbol, I think I\'ve seen this before... ', 12, 0, 100.0, 5, 0, 0, 0, 3, 'Brann Bronzebeard'),
(39908, 1, 0, 'Right, let\'s go! Just need to input the final entry sequence into the door mechanism... and...', 12, 0, 100.0, 5, 0, 20897, 0, 3, 'Brann Bronzebeard'),
(39908, 2, 0, 'That did the trick! The control room should be right behind this... oh... wow...', 12, 0, 100.0, 5, 0, 20898, 0, 3, 'Brann Bronzebeard'),
(39908, 3, 0, 'What? This isn\'t the control room! There\'s another entire defense mechanism in place, and the blasted Rock Troggs broke into here somehow. Troggs. Why did it have to be Troggs!', 12, 0, 100.0, 5, 0, 20899, 0, 3, 'Brann Bronzebeard'),
(39908, 4, 0, 'Ok, let me think a moment.', 12, 0, 100.0, 1, 0, 20900, 0, 3, 'Brann Bronzebeard'),
(39908, 5, 0, 'Mirrors pointing all over the place.', 12, 0, 100.0, 25, 0, 20902, 0, 3, 'Brann Bronzebeard'),
(39908, 6, 0, 'Four platforms with huge elementals.', 12, 0, 100.0, 25, 0, 20901, 0, 3, 'Brann Bronzebeard'),
(39908, 7, 0, 'I got it! I saw a tablet that mentioned this chamber. This is the Vault of Lights! Ok, simple enough. I need you adventurers to take out each of the four elementals to trigger the opening sequence for the far door!', 12, 0, 100.0, 5, 0, 20903, 0, 3, 'Brann Bronzebeard'),
(39908, 8, 0, 'One down!', 14, 0, 100.0, 5, 0, 20904, 0, 3, 'Brann Bronzebeard'),
(39908, 9, 0, 'Another one down! Just look at those light beams! They seem to be connecting to the far door!', 14, 0, 100.0, 5, 0, 20905, 0, 3, 'Brann Bronzebeard'),
(39908, 10, 0, 'One more elemental to go! The door is almost open!', 14, 0, 100.0, 5, 0, 20906, 0, 3, 'Brann Bronzebeard'),
(39908, 11, 0, 'That\'s it, you\'ve done it! The vault door is opening! Now we can... oh, no!', 14, 0, 100.0, 5, 0, 20907, 0, 3, 'Brann Bronzebeard'),
(39908, 12, 0, 'We\'ve done it! The control room is breached!', 14, 0, 100.0, 5, 0, 23709, 0, 3, 'Brann Bronzebeard'),
(39908, 13, 0, 'Here we go! Now this should only take a moment...', 14, 0, 100.0, 5, 0, 23710, 0, 3, 'Brann Bronzebeard'),
(40808, 0, 0, '%s buries itself in the sand!', 16, 0, 100.0, 0, 0, 0, 0, 0, ''),
(43612, 0, 0, 'Begone infidels, you are not welcome here!', 14, 0, 100.0, 0, 0, 19735, 0, 0, 'High Prophet Barim'),
(43612, 1, 0, 'May peace find you now.', 14, 0, 100.0, 0, 0, 19738, 0, 0, 'High Prophet Barim'),
(43612, 1, 1, 'The heavens take you!', 14, 0, 100.0, 0, 0, 19736, 0, 0, 'High Prophet Barim'),
(43612, 2, 0, 'Kneel before me and repent!', 14, 0, 100.0, 0, 0, 19737, 0, 0, 'High Prophet Barim'),
(43612, 3, 0, 'Death is only the beginning!', 14, 0, 100.0, 0, 0, 19733, 0, 0, 'High Prophet Barim'),
(43873, 0, 0, 'The wind abruptly shifts direction at %s\' command!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Altairus - Announce Call the Wind'),
(43873, 1, 0, '%s senses $n\'s cowardice and unleashes a blast of lightning!', 16, 0, 100.0, 0, 0, 0, 0, 0, 'Altairus - Announce Lightning Blast'),
(43875, 0, 0, 'YOU tread upon the sacrosanct! Mortals have no place amidst the clouds.', 14, 0, 100.0, 0, 0, 20867, 0, 0, 'Asaad to Player'),
(43875, 1, 0, 'Al\'Akir, your servant calls for aid!', 14, 0, 100.0, 0, 0, 20869, 0, 0, 'Asaad'),
(43875, 2, 0, '%s conjures a temporary grounding field!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Asaad'),
(43875, 3, 0, 'The winds take me!', 14, 0, 100.0, 0, 0, 20870, 0, 0, 'Asaad to Player'),
(43878, 0, 0, 'Filthy beasts! Your presence in Skywall will not be tolerated!', 14, 0, 100.0, 0, 0, 20876, 0, 0, 'Grandvizier Ertan - Aggro'),
(43878, 1, 0, '%s retracts her cyclone shield!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Grandvizier Ertan - Announce Storms Edge'),
(43934, 0, 0, 'A soul fragment merges souls with the Harbinger of Darkness!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Soul Fragment'),
(44577, 0, 0, 'Invaders, you shall go no further!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'General Husam to Player'),
(44577, 1, 0, 'Insolent rat!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'General Husam to Player'),
(44577, 2, 0, 'Murkash!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'General Husam'),
(44577, 3, 0, '|TInterface\\Icons\\spell_nature_earthquake.blp:20|t%s begins to cast |cFFFF0000|Hspell:83445|h[Shockwave]!|h|r', 41, 0, 100.0, 0, 0, 0, 0, 0, 'General Husam'),
(44577, 4, 0, 'Tread Lightly.', 14, 0, 100.0, 0, 0, 0, 0, 0, 'General Husam'),
(44577, 5, 0, 'Siamat must not be freed! Turn back before it is too late!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'General Husam to Player'),
(44819, 0, 0, 'I. AM. UNLEASHED!', 14, 0, 100.0, 0, 0, 20231, 0, 2, 'Siamat - Intro'),
(44819, 1, 0, 'Winds of the south, rise and come to your master\'s aid!', 14, 0, 100.0, 0, 0, 20227, 0, 0, 'Siamat - Aggro 1'),
(44819, 2, 0, 'Cower before the tempest storm!', 14, 0, 100.0, 0, 0, 20228, 0, 0, 'Siamat - Wailing Winds 1'),
(44819, 3, 0, 'Nothing more than dust in the wind.', 14, 0, 100.0, 0, 0, 20232, 0, 0, 'Siamat - Slay'),
(44819, 4, 0, 'The sky... Beckons...', 14, 0, 100.0, 0, 0, 20226, 0, 0, 'Siamat - Death'),
(45377, 0, 0, 'Bwaaaah! You no take da treasure!!!', 12, 0, 100.0, 0, 0, 0, 0, 0, 'Augh'),
(45377, 1, 0, 'Bwagauugh!!! Augh feed you to da crocs!!!', 12, 0, 100.0, 0, 0, 0, 0, 0, 'Augh'),
(45704, 0, 0, '%s realizes it\'s been spotted and quickly plays dead!', 16, 0, 100.0, 0, 0, 0, 0, 0, 'Lurking Tempest'),
(45870, 0, 0, 'It shall be I that earns the favor of our lord by casting out the intruders. My calmest wind shall still prove too much for them!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Anshal - Aggro'),
(45870, 1, 0, 'You think to outrun the wind? A fatal mistake.', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Anshal - Out of Range'),
(45870, 2, 0, 'My power grows feeble, brothers. I shamefully must rely on you for a time.', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Anshal - Gather Strength'),
(45870, 3, 0, '%s begins to gather strength from the remaining Wind Lords!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'Anshal - Announce Gather Strength'),
(45870, 4, 0, 'The power of our winds, UNLEASHED!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Anshal - Special Ability'),
(45870, 5, 0, 'Begone, outsider!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Anshal - Slay 1'),
(45870, 5, 1, 'Your presence shall no longer defile our home!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Anshal - Slay 2'),
(45871, 0, 0, 'The honor of slaying the interlopers shall be mine, brothers! Their feeble bodies will freeze solid from my wind\'s icy chill!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Nezir - Aggro'),
(45871, 1, 0, 'You throw away your honor and flee as cowards? Then die!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Nezir - Out of Range'),
(45871, 2, 0, 'Brothers, beware! These mortals are dangerous. I must pause and gather my strength.', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Nezir - Gather Strength'),
(45871, 3, 0, '%s begins to gather strength from the remaining Wind Lords!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'Nezir - Announce Gather Strength'),
(45871, 4, 0, 'The power of our winds, UNLEASHED!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Nezir - Special Ability'),
(45871, 5, 0, 'Frozen solid.', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Nezir - Slay 1'),
(45871, 5, 1, 'Another mortal has taken their last breath!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Nezir - Slay 2'),
(45872, 0, 0, 'As I am the strongest wind, it shall be I that tears the invaders apart!', 14, 0, 100.0, 0, 0, 0, 0, 0, 'Rohash - Aggro'),
(45872, 1, 0, 'Why do you flee, mortals? There is nowhere you can run or hide here!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Rohash - Out of Range'),
(45872, 2, 0, 'The intruders stand fast, brothers, I cannot break them. Allow me a brief respite to strengthen my winds.', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Rohash - Gather Strength'),
(45872, 3, 0, '%s begins to gather strength from the remaining Wind Lords!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'Rohash - Announce Gather Strength'),
(45872, 4, 0, 'The power of our winds, UNLEASHED!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Roash - Special Ability'),
(45872, 5, 0, 'Blown away!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Rohash - Slay 1'),
(45872, 5, 1, 'Mere dust...', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Roash - Slay 2'),
(45872, 6, 0, '|TInterface\\Icons\\spell_nature_cyclone.blp:20|t%s begins to cast|cFFFF9A20|Hspell:86193|h [Wind Blast]!|r', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Rohash - Announce Wind Blast'),
(45979, 0, 0, 'A stray jolt from the Foe Reaper has disrupted the foundry controls!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF'),
(45979, 1, 0, 'The molten slag begins to bubble furiously!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF'),
(45979, 2, 0, 'The cannon was rigged with an explosive trap!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF to Player'),
(45979, 3, 0, 'A shadowy figure appears in the ship\'s cabin!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF to Player'),
(45979, 4, 0, 'The Nightmare Elixir takes hold!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF to Steam Valve'),
(45979, 5, 0, 'The nightmare shifts!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF to Player'),
(45979, 6, 0, 'Save Emme Harrington!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF to Player'),
(45979, 7, 0, 'Save Erik Harrington!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF'),
(45979, 8, 0, 'Save Calissa Harrington!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF'),
(45979, 9, 0, 'The Nightmare Elixir wears off!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'General Purpose Bunny JMF'),
(46753, 0, 0, 'The Conclave of Wind has dissipated. Your honorable conduct and determination have earned you the right to face me in battle, mortals. I await your assault on my platform! Come!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Conclave of Wind defeated'),
(46753, 1, 0, 'Your challenge is accepted, mortals! Know that you face Al\'Akir, Elemental Lord of Air! You have no hope of defeating me!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Aggro'),
(46753, 2, 0, '|TINTERFACE\\ICONS\\Spell_Frost_WindWalkOn.blp:20|t%s begins to cast |cFFFF0000|Hspell:87770|h[Wind Burst]|h|r!', 41, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Announce Wind Burst'),
(46753, 3, 0, 'Winds! Obey my command!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Squall Line'),
(46753, 4, 0, 'Your futile persistance angers me!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Phase 2'),
(46753, 5, 0, 'Storms! I summon you to my side!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Stormling'),
(46753, 6, 0, 'Enough! I will no longer be contained!', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Phase 3'),
(46753, 7, 0, 'This little one shall vex me no longer.', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Slay 1'),
(46753, 7, 1, 'Like swatting insects...', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Slay 2'),
(46753, 8, 0, 'After every storm, comes the calm...', 14, 0, 100.0, 0, 0, 0, 0, 3, 'Al\'Akir - Death'),
(48139, 0, 0, '%s begins to aim a charged shot at $n!', 16, 0, 100.0, 0, 0, 0, 0, 0, 'Temple Swiftstalker - Charged Shot'),
(49045, 0, 0, 'Augh appears from the distance!', 41, 0, 0.0, 0, 0, 0, 0, 0, 'Augh - Intro 1'),
(49045, 1, 0, 'GAAAH! How you kill croc?!', 12, 0, 0.0, 53, 0, 0, 0, 0, 'Augh - Intro 2'),
(49045, 2, 0, 'Augh smart! Augh already steal treasure while you no looking!', 12, 0, 0.0, 1, 0, 0, 0, 0, 'Augh - Intro 3'),
(49045, 3, 0, 'Augh da boss! Oh yeah!', 12, 0, 0.0, 0, 0, 0, 0, 0, 'Augh Taunt'),
(49045, 4, 0, 'Augh steal your treasure. Uhn uhn uhnnn!', 12, 0, 0.0, 0, 0, 0, 0, 0, 'Augh Taunt'),
(49045, 5, 0, 'Who bad?! Augh bad!! Ugn!', 12, 0, 0.0, 0, 0, 0, 0, 0, 'Augh Taunt'),
(52558, 0, 0, 'Hah? Hruumph? Soft little fleshy-things? Here? Nuisances, nuisances!', 14, 0, 100.0, 0, 0, 24537, 0, 0, 'Lord Rhyolith - Engage'),
(52558, 1, 0, 'I\'ll crush you underfoot!', 14, 0, 100.0, 0, 0, 24557, 0, 0, 'Lord Rhyolith - Concussive Stomp 1'),
(52558, 1, 1, 'Stomp now.', 14, 0, 100.0, 0, 0, 24556, 0, 0, 'Lord Rhyolith - Concussive Stomp 2'),
(52558, 2, 0, '%s begins to drink from the magma pools.', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Lord Rhyolith - Announce Drink Magma'),
(52558, 3, 0, 'Buuurrrnn!', 14, 0, 100.0, 0, 0, 24550, 0, 0, 'Lord Rhyolith - Heated Volcano 1'),
(52558, 3, 1, 'Succumb to living flame.', 14, 0, 100.0, 0, 0, 24551, 0, 0, 'Lord Rhyolith - Heated Volcano 2'),
(52558, 4, 0, '%s\'s armor is weakened by the active volcano.', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Lord Rhyolith - Announce Obsidian Armor Weakened'),
(52558, 5, 0, 'Uurrghh now you... you infuriate me!', 14, 0, 100.0, 0, 0, 24543, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened 1'),
(52558, 5, 1, 'Oww now hey.', 14, 0, 100.0, 0, 0, 24540, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened 2'),
(52558, 5, 2, 'Graaahh!', 14, 0, 100.0, 0, 0, 24541, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened 3'),
(52558, 5, 3, 'Augh - smooshy little pests, look what you\'ve done!', 14, 0, 100.0, 0, 0, 24542, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened 4'),
(52558, 9, 0, 'Finished.', 14, 0, 100.0, 0, 0, 24546, 0, 0, 'Lord Rhyolith - Slay 1'),
(52558, 9, 1, 'So soft!', 14, 0, 100.0, 0, 0, 24547, 0, 0, 'Lord Rhyolith - Slay 2'),
(52558, 9, 2, 'Squeak, little pest.', 14, 0, 100.0, 0, 0, 24548, 0, 0, 'Lord Rhyolith - Slay 3'),
(52571, 0, 0, 'Very well. Witness the raw power of my new Lord!', 14, 0, 100.0, 0, 0, 24464, 0, 3, 'Majordomo Staghelm - Intro'),
(52571, 1, 0, 'The master\'s power takes on many forms...', 14, 0, 100.0, 0, 0, 24483, 0, 0, 'Majordomo Staghelm - Scorpion Form'),
(52571, 2, 0, '|TInterface\\Icons\\inv_mount_hordescorpiong.blp:20|t%s transforms into a |c0087CEFA|Hspell:98379|h[Scorpion]|h|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Majordomo Staghelm - Announce Scorpion Form'),
(52571, 3, 0, 'Behold the rage of the Firelands!', 14, 0, 100.0, 0, 0, 24485, 0, 0, 'Majordomo Staghelm - Cat Form'),
