(52571, 6, 0, '|c00FF0000Searing Seeds begin to grow!|r', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Majordomo Staghelm - Announce Searing Seeds'),
(52571, 7, 0, 'Nothing but ash!', 14, 0, 100.0, 0, 0, 24478, 0, 0, 'Majordomo Staghelm - Burning Orbs'),
(52571, 8, 0, '|c00FF0000%s summons Burning Orbs!|r', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Majordomo Staghelm - Announce Burning Orbs'),
(52571, 9, 0, 'Burn.', 14, 0, 100.0, 0, 0, 24477, 0, 0, 'Majordomo Staghelm - Slay'),
(52571, 9, 1, 'Soon ALL of Azeroth will burn!', 14, 0, 100.0, 0, 0, 24479, 0, 0, 'Majordomo Staghelm - Slay'),
(52571, 9, 2, 'So much power!', 14, 0, 100.0, 0, 0, 24480, 0, 0, 'Majordomo Staghelm - Slay'),
(52571, 9, 3, 'You stood in the fire!', 14, 0, 100.0, 0, 0, 24481, 0, 0, 'Majordomo Staghelm - Slay'),
(52571, 10, 0, 'My studies... had only just begun...', 14, 0, 100.0, 0, 0, 24471, 0, 0, 'Majordomo Staghelm to Player'),
(52571, 11, 0, 'Well, well. I admire your tenacity. Baleroc stood guard over this keep for a thousand mortal lifetimes.', 14, 0, 100.0, 0, 0, 24473, 0, 3, 'Majordomo Staghelm - Baleroc Outro 1'),
(52571, 12, 0, 'But none may enter the Firelord\'s abode!', 14, 0, 100.0, 0, 0, 24474, 0, 3, 'Majordomo Staghelm - Baleroc Outro'),
(52571, 13, 0, 'Beg for mercy now, and I may yet allow you to live. Well, \"heroes?\" What is your answer?', 14, 0, 100.0, 0, 0, 24475, 0, 3, 'Majordomo Staghelm - Baleroc Outro'),
(53494, 0, 0, 'You are forbidden from my master\'s domain, mortals.', 14, 0, 100.0, 0, 0, 24441, 0, 0, 'Baleroc'),
(53494, 1, 0, 'Fool mortals. Hurl yourselves into your own demise!', 14, 0, 100.0, 0, 0, 24446, 0, 0, 'Baleroc'),
(53494, 2, 0, 'Burn beneath my molten fury!', 14, 0, 100.0, 0, 0, 24459, 0, 0, 'Baleroc'),
(53494, 3, 0, 'By the Firelord\'s command, you, too, shall perish!', 14, 0, 100.0, 0, 0, 24447, 0, 0, 'Baleroc'),
(53494, 4, 0, 'None shall pass!', 14, 0, 100.0, 0, 0, 24452, 0, 0, 'Baleroc'),
(53494, 4, 1, 'You have been judged.', 14, 0, 100.0, 0, 0, 24449, 0, 0, 'Baleroc'),
(53494, 4, 2, 'Behold your weakness.', 14, 0, 100.0, 0, 0, 24451, 0, 0, 'Baleroc'),
(53494, 5, 0, 'Your flesh is forfeit to the fires of this realm.', 14, 0, 100.0, 0, 0, 24450, 0, 0, 'Baleroc'),
(53494, 6, 0, '%s goes into a berserker rage!', 16, 0, 100.0, 0, 0, 0, 0, 0, 'Baleroc'),
(53494, 7, 0, 'Mortal filth... the master\'s keep is forbidden...', 14, 0, 100.0, 0, 0, 24444, 0, 0, 'Baleroc'),
(53494, 8, 0, '|TInterface\\Icons\\inv_sword_09.blp:20|t%s readies his |cFFFF0000Inferno Blade|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Baleroc'),
(53494, 9, 0, '|TInterface\\Icons\\spell_shadow_curse:20|t%s readies his |cFF551A8BDecimation Blade|r!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Baleroc'),
(53772, 1, 0, 'I\'ll crush you underfoot!', 14, 0, 100.0, 0, 0, 24557, 0, 0, 'Lord Rhyolith - Concussive Stomp 1'),
(53772, 1, 1, 'Stomp now.', 14, 0, 100.0, 0, 0, 24556, 0, 0, 'Lord Rhyolith - Concussive Stomp 2'),
(53772, 6, 0, '%s stumbles as his armor is shattered!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Lord Rhyolith - Announce Armor Shattered'),
(53772, 7, 0, 'Eons I have slept undisturbed... Now this... Creatures of flesh, now you will BURN!', 14, 0, 100.0, 0, 0, 24558, 0, 0, 'Lord Rhyolith - Armor Shattered'),
(53772, 8, 0, 'Broken. Mnngghhh... broken...', 14, 0, 100.0, 0, 0, 24545, 0, 0, 'Lord Rhyolith - Death'),
(53772, 9, 0, 'Finished.', 14, 0, 100.0, 0, 0, 24546, 0, 0, 'Lord Rhyolith - Slay 1'),
(53772, 9, 1, 'So soft!', 14, 0, 100.0, 0, 0, 24547, 0, 0, 'Lord Rhyolith - Slay 2'),
(53772, 9, 2, 'Squeak, little pest.', 14, 0, 100.0, 0, 0, 24548, 0, 0, 'Lord Rhyolith - Slay 3'),
(53795, 0, 0, 'The Molten Eggs begin to crack and splinter!', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Molten Egg - EMOTE_CRACKING_EGGS'),
(54192, 0, 0, 'Hah? Hruumph? Soft little fleshy-things? Here? Nuisances, nuisances!', 14, 0, 100.0, 0, 0, 24537, 0, 0, 'Lord Rhyolith - Engage'),
(54192, 1, 0, 'I\'ll crush you underfoot!', 14, 0, 100.0, 0, 0, 24557, 0, 0, 'Lord Rhyolith - Concussive Stomp 1'),
(54192, 1, 1, 'Stomp now.', 14, 0, 100.0, 0, 0, 24556, 0, 0, 'Lord Rhyolith - Concussive Stomp 2'),
(54192, 2, 0, '%s begins to drink from the magma pools.', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Lord Rhyolith - Announce Drink Magma'),
(54192, 3, 0, 'Buuurrrnn!', 14, 0, 100.0, 0, 0, 24550, 0, 0, 'Lord Rhyolith - Heated Volcano 1'),
(54192, 3, 1, 'Succumb to living flame.', 14, 0, 100.0, 0, 0, 24551, 0, 0, 'Lord Rhyolith - Heated Volcano 2'),
(54192, 4, 0, '%s\'s armor is weakened by the active volcano.', 41, 0, 100.0, 0, 0, 0, 0, 0, 'Lord Rhyolith - Announce Obsidian Armor Weakened'),
(54192, 5, 0, 'Uurrghh now you... you infuriate me!', 14, 0, 100.0, 0, 0, 24543, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened'),
(54192, 5, 1, 'Oww now hey.', 14, 0, 100.0, 0, 0, 24540, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened'),
(54192, 5, 2, 'Graaahh!', 14, 0, 100.0, 0, 0, 24541, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened 3'),
(54192, 5, 3, 'Augh - smooshy little pests, look what you\'ve done!', 14, 0, 100.0, 0, 0, 24542, 0, 0, 'Lord Rhyolith - Obsidian Armor Weakened 4'),
(54192, 9, 0, 'Finished.', 14, 0, 100.0, 0, 0, 24546, 0, 0, 'Lord Rhyolith - Slay 1'),
(54192, 9, 1, 'So soft!', 14, 0, 100.0, 0, 0, 24547, 0, 0, 'Lord Rhyolith - Slay 2'),
(54192, 9, 2, 'Squeak, little pest.', 14, 0, 100.0, 0, 0, 24548, 0, 0, 'Lord Rhyolith - Slay 3'),
(54199, 0, 0, 'Hah? Hruumph? Soft little fleshy-things? Here? Nuisances, nuisances!', 14, 0, 100.0, 0, 0, 24537, 0, 0, 'Lord Rhyolith - Engage'),
