(54199, 9, 2, 'Squeak, little pest.', 14, 0, 100.0, 0, 0, 24548, 0, 0, 'Lord Rhyolith - Slay 3'),
(56102, 0, 0, 'I will slow the Destroyer\'s attacks when I can.', 14, 0, 100.0, 0, 0, 25949, 0, 1, 'Nozdormu - Introduce Ability'),
(56102, 1, 0, 'Hurry, heroes. In mere moments Deathwing\'s Cataclysm will complete what he begun and end the world. Join me in the attack, now!', 14, 0, 100.0, 0, 0, 25951, 0, 1, 'Nozdormu - Cataclysm'),
(56102, 2, 0, 'Press the attack, heroes.', 14, 0, 100.0, 0, 0, 25950, 0, 1, 'Nozdormu - Phase 2'),
(56102, 3, 0, 'It is time. I will expend everything to bind every thread here, now, around the Dragon Soul. What comes to pass will NEVER be undone.', 14, 0, 100.0, 0, 0, 26600, 0, 1, 'Nozdormu - Charge Dragon Soul');
